import base64

b64_str = """..."""

# Clean any whitespace or newlines if needed
b64_clean = "".join(b64_str.split())

with open("src/assets/images/marc_williamson_user.jpg", "wb") as f:
    f.write(base64.b64decode(b64_clean))

print("Successfully saved image to src/assets/images/marc_williamson_user.jpg")
